  "sql": "WITH _base AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    customers.id AS \"orders.customers.id\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  WHERE\n    NOT customers.region_id IS NULL\n  GROUP BY\n    customers__regions.name,\n    customers.id\n), _cm_orders__amount_sum_partition_by_customers_regions_name AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.region_revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  WHERE\n    NOT customers.region_id IS NULL\n  GROUP BY\n    customers__regions.name\n), base AS (\n  SELECT\n    _base.\"orders.customers.regions.name\",\n    _base.\"orders.customers.id\",\n    _base.\"orders.revenue\",\n    _cm_orders__amount_sum_partition_by_customers_regions_name.\"orders.region_revenue\"\n  FROM _base\n  LEFT JOIN _cm_orders__amount_sum_partition_by_customers_regions_name\n    ON _base.\"orders.customers.regions.name\" IS NOT DISTINCT FROM _cm_orders__amount_sum_partition_by_customers_regions_name.\"orders.customers.regions.name\"\n), step1 AS (\n  SELECT\n    \"orders.customers.regions.name\",\n    \"orders.customers.id\",\n    \"orders.revenue\",\n    \"orders.region_revenue\",\n    CASE\n      WHEN \"orders.revenue\" IS NULL\n      THEN NULL\n      ELSE RANK() OVER (\n        PARTITION BY \"orders.customers.regions.name\", CASE WHEN \"orders.revenue\" IS NULL THEN 1 ELSE 0 END\n        ORDER BY \"orders.revenue\" DESC\n      )\n    END AS \"orders._rank_inner\"\n  FROM base\n)\nSELECT\n  \"orders.customers.regions.name\",\n  \"orders.customers.id\",\n  \"orders.revenue\",\n  \"orders.region_revenue\"\nFROM (\n  SELECT\n    \"orders.customers.regions.name\",\n    \"orders.customers.id\",\n    \"orders.revenue\",\n    \"orders.region_revenue\",\n    \"orders._rank_inner\"\n  FROM step1\n  WHERE\n    \"orders._rank_inner\" <= 2\n) AS _outer\nORDER BY\n  \"orders.customers.regions.name\" ASC,\n  \"orders.revenue\" DESC\nLIMIT 101"
